#!/usr/bin/env python3
"""Prepare the Android project generated by `flutter create` for the app lock.

The system dialog for fingerprint, face or device PIN (plugin local_auth)
needs three things the Flutter template does not bring:

* ``MainActivity`` extends ``FlutterFragmentActivity``,
* the permission ``USE_BIOMETRIC``,
* an AppCompat theme on the activity.

The script is idempotent and fails loudly when the template changed in a way
it does not understand.
"""
from __future__ import annotations

import re
import sys
from pathlib import Path

PERMISSION = '<uses-permission android:name="android.permission.USE_BIOMETRIC"/>'
THEME = "Theme.AppCompat.DayNight.NoActionBar"
DEFAULT_MAIN = Path("android/app/src/main")


class AppLockSetupError(RuntimeError):
    """The Android project does not look like the Flutter template."""


def fragment_activity(code: str) -> str:
    """Return MainActivity.kt based on FlutterFragmentActivity."""
    if "FlutterFragmentActivity" in code:
        return code
    code, count = re.subn(r"\bFlutterActivity\b", "FlutterFragmentActivity", code)
    if count != 2:
        raise AppLockSetupError(f"MainActivity.kt hat eine unerwartete Form ({count} Ersetzungen).")
    return code


def biometric_permission(manifest: str) -> str:
    """Return the manifest with the USE_BIOMETRIC permission."""
    if re.search(r'<uses-permission\s+android:name="android\.permission\.USE_BIOMETRIC"\s*/>', manifest):
        return manifest
    opening = re.search(r"<manifest\b[^>]*>", manifest, re.DOTALL)
    if opening is None:
        raise AppLockSetupError("Kein <manifest>-Element gefunden.")
    return manifest[: opening.end()] + "\n    " + PERMISSION + manifest[opening.end() :]


def appcompat_themes(styles: str) -> str:
    """Return styles.xml with both activity themes based on AppCompat."""
    styles, count = re.subn(
        r'(<style name="(?:LaunchTheme|NormalTheme)" parent=")[^"]+(")',
        rf"\g<1>{THEME}\g<2>",
        styles,
    )
    if count != 2:
        raise AppLockSetupError(f"styles.xml hat eine unerwartete Form ({count} Themes).")
    return styles


def main(argv: list[str]) -> int:
    root = Path(argv[1]) if len(argv) > 1 else DEFAULT_MAIN
    try:
        activities = list(root.rglob("MainActivity.kt"))
        if len(activities) != 1:
            raise AppLockSetupError(f"Erwartet genau eine MainActivity.kt, gefunden: {len(activities)}.")
        activities[0].write_text(fragment_activity(activities[0].read_text(encoding="utf-8")), encoding="utf-8")

        manifest = root / "AndroidManifest.xml"
        if not manifest.is_file():
            raise AppLockSetupError(f"Manifest nicht gefunden: {manifest}")
        manifest.write_text(biometric_permission(manifest.read_text(encoding="utf-8")), encoding="utf-8")

        styles = sorted((root / "res").glob("values*/styles.xml"))
        if not styles:
            raise AppLockSetupError("Keine styles.xml gefunden.")
        for path in styles:
            path.write_text(appcompat_themes(path.read_text(encoding="utf-8")), encoding="utf-8")
    except AppLockSetupError as error:
        print(f"App-Sperre nicht vorbereitet: {error}", file=sys.stderr)
        return 1
    print("Android: MainActivity, Berechtigung und Themes für die App-Sperre vorbereitet.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))
